typedef unsigned int nlUint32;
typedef int nlInt32;
typedef unsigned int nslSoundId;

#define NSL_NUM_SOUNDS 256
#define NSL_ID_MASK 0xFFFFFC00
#define NSL_SLOT_MASK 0x000003FF
#define NSL_INVALID_ID 0
#define NSL_GET_SLOT_FROM_ID(x) (x&NSL_SLOT_MASK)

void nslFatal(const char *Format, ...);

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  nlInt32 pauseCount;
  nlInt32 dampenCount;
  nslSoundId myId;
  nslSoundId mySource;
  nslSoundId myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char beforeSoundSlots[0xC040];
  nslSound soundSlots[NSL_NUM_SOUNDS];
  char beforeInitialized[0x4010];
  nlInt32 initialized;
  char beforeOn[0x2C];
  bool on;
};

extern nslSystem nsl;

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  nslSoundId checkSlot = (checkId & NSL_SLOT_MASK);
  nslSoundId upCheckId = (checkId & NSL_ID_MASK);
  if (checkId == NSL_INVALID_ID)
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(nsl.soundSlots[checkSlot].used))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkSlot < NSL_NUM_SOUNDS))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkId == nsl.soundSlots[checkSlot].myId))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(upCheckId > 0))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (checkSlot > NSL_NUM_SOUNDS)
    nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal("NSL NOT INITIALIZED");
}

#define ASSERT_SOUND_ID_VALID(checkId) _nslCheckSoundIdValidity(checkId)
#define ASSERT_NSL_INITIALIZED() _nslInitialized()

void nslPauseGuardSound(nslSoundId soundToGuard)
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_SOUND_ID_VALID(soundToGuard);
  int pc = nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].pauseCount;
  if (!(pc <= 0))
    nslFatal("Trying to pause guard a paused sound!");
  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].pauseCount <= 0)
    nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToGuard)].pauseCount = -1;
}
